import sys

def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def main():
    if len(sys.argv) < 2:
        print("Usage: python3 prime.py <integer>")
        sys.exit(1)
    num = int(sys.argv[1])
    if is_prime(num):
        print("prime")
    else:
        print("composite")

if __name__ == "__main__":
    main()
